/**
 * Test flow for getLatestResponseTextFromEmail action
 * Demonstrates getting the latest response text from an email thread
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testGetLatestResponseTextFromEmail = Flow(
    {
        $id: Now.ID['test_get_latest_response_text_from_email_flow'],
        name: 'Test Get Latest Response Text From Email',
        description: 'Tests the getLatestResponseTextFromEmail core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_get_latest_response_text_from_email_trigger'] },
        {
            table: 'sys_email',
            condition: 'type=received',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        const result = wfa.action(
            action.core.getLatestResponseTextFromEmail,
            { $id: Now.ID['test_get_latest_response_text_from_email_action'] },
            {
                email_record: wfa.dataPill(_params.trigger.current.sys_id, 'reference'),
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_get_latest_response_text_from_email_log'] },
            {
                log_level: 'info',
                log_message: `getLatestResponseTextFromEmail outputs: latest_response_text=${wfa.dataPill(result.latest_response_text, 'string')}`,
            }
        )
    }
)
